package vn.svframe.svframemmo.skill.list;
import net.minecraft.block.Blocks;import vn.svframe.svframelib.skill.SkillMetadata;import vn.svframe.svframelib.skill.handler.*;import vn.svframe.svframelib.skill.result.def.SimpleSkillResult;import vn.svframe.svframelib.util.configobject.ConfigObject;import vn.svframe.svframemmo.api.event.PlayerResourceUpdateEvent;
@BuiltinSkillHandler(mods={"extra"},triggerable=false) public final class Neptune_Gift extends SkillHandler<SimpleSkillResult>{private static boolean hook;public Neptune_Gift(ConfigObject c){super(c);install();}private static synchronized void install(){if(hook)return;hook=true;PlayerResourceUpdateEvent.EVENT.register(e->{if(e.getUpdateReason().isRegeneration()||!e.getPlayer().getWorld().getBlockState(e.getPlayer().getBlockPos()).isOf(Blocks.WATER)||e.getDifference()<0)return;var h=vn.svframe.svframelib.SVFrameLib.inst().getSkills().getHandler("NEPTUNE_GIFT");if(h==null)return;var passive=e.getData().getMMOPlayerData().getPassiveSkillMap().getSkill(h);if(passive==null)return;double extra=e.getData().getMMOPlayerData().getSkillModifierMap().calculateValue(passive.getTriggeredSkill(),"extra");e.setNewAmount(e.getNewAmount()+e.getDifference()*extra/100d);});}public SimpleSkillResult getResult(SkillMetadata m){throw new UnsupportedOperationException("NEPTUNE_GIFT is passive-only");}public void whenCast(SimpleSkillResult r,SkillMetadata m){throw new UnsupportedOperationException("NEPTUNE_GIFT is passive-only");}}
